"use client";
/* Modem, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Modem(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("modem"); }, []);
  return React.createElement("piix-sprite", { "name": "modem", ...piixAttrs(props) });
}

export default Modem;
